use super::*;
#[tokio::test]async fn builder_observes_only_one_peer(){let(tap,rx)=Tap::memory(16);let b=ObserverBuilder{tap,consumed:AtomicBool::new(false)};let first=b.build("first").unwrap();let second=b.build("second").unwrap();let sink=Arc::new(Sink::default());let a=first.bind_local_stream(&info(),sink.clone()).await;let c=second.bind_local_stream(&info(),sink.clone()).await;a.write(&packet(),&Attributes::new()).await.unwrap();c.write(&packet(),&Attributes::new()).await.unwrap();assert_eq!(sink.packets.lock().unwrap().len(),2);assert_eq!(rx.try_iter().filter(|e|matches!(e.data,Data::Rtp{..})).count(),1);first.close().await.unwrap();second.close().await.unwrap();}
#[tokio::test]async fn truncated_feedback_is_counted_without_altering_return(){let(tap,path)=Tap::test_file();let source=Arc::new(ReadOnce{packets:Mutex::new(Some(vec![Box::new(TransportLayerNack{sender_ssrc:1,media_ssrc:42,nacks:vec![NackPair{packet_id:12,lost_packets:3};65]})])),calls:AtomicUsize::new(0)});let reader=RtcpIn{inner:source,tap:tap.clone()};let mut buf=[0;1500];let(p,_)=reader.read(&mut buf,&Attributes::new()).await.unwrap();assert_eq!(p[0].as_any().downcast_ref::<TransportLayerNack>().unwrap().nacks.len(),65);tap.close();let until=std::time::Instant::now()+std::time::Duration::from_secs(2);loop{let text=std::fs::read_to_string(&path).unwrap();if let Some(v)=text.lines().last().and_then(|s|serde_json::from_str::<serde_json::Value>(s).ok()){if v["type"]=="footer"{assert_eq!(v["omitted"],1);assert_eq!(v["observation_complete"],false);break;}}assert!(std::time::Instant::now()<until);tokio::time::sleep(std::time::Duration::from_millis(10)).await;}}
#[tokio::test]async fn disabled_closed_tap_preserves_same_inner_writer_errors(){let(tap,rx)=Tap::memory(4);tap.close();let o=observer(tap);let sink=Arc::new(Sink::default());sink.error.store(true,Ordering::Relaxed);let writer=o.bind_local_stream(&info(),sink.clone()).await;assert!(writer.write(&packet(),&Attributes::new()).await.unwrap_err().to_string().contains("sentinel-write-error"));assert_eq!(sink.packets.lock().unwrap().len(),1);assert!(rx.try_recv().is_err());}
